import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;

public class Main {
  public static void main(String[] args) throws Exception {
      Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/mibase", "tuusuario", "tucontraseña");

      // En Java usamos '?' como placeholder
      String sql = "INSERT INTO clientes (nombre, direccion) VALUES (?, ?)";
      PreparedStatement pstmt = conn.prepareStatement(sql);

      pstmt.setString(1, "John");
      pstmt.setString(2, "Highway 21");

      int afectadas = pstmt.executeUpdate();
      System.out.println(afectadas + " registro insertado.");
  }
}
